//! The tool-source contracts, checked against the pinned reference's own answers.
//!
//! `tests/fixtures/phase5a/oracle.json` is generated by the pinned reference running
//! `src/sources/models.py`, so every acceptance, refusal and dump here is the oracle's verdict —
//! not an expectation written by hand. A divergence fails this test instead of reaching an
//! operator's source registration.

use std::collections::BTreeSet;

use serde_json::{Value, json};

use mcp_server_rs::sources::models::{
    FORBIDDEN_HEADERS, RevisionOnly, SourceAuth, SourceCreate, SourceUpdate, SourceView,
    TenantSourceCreate, TenantSourceUpdate, TokenUpdate, checked_tenant_url, needs_secret,
};

fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/phase5a/oracle.json"
    );
    let text = std::fs::read_to_string(path).expect("the phase-5A fixture file exists");
    serde_json::from_str(&text).expect("the phase-5A fixture file is JSON")
}

/// Parse a fixture body into the named model and serialise the accepted model back. The caller
/// compares the serialised value with the fixture's `dump`; comparing `Value`s ignores key order.
fn parse_and_dump(model: &str, body: &Value) -> Result<Value, serde_json::Error> {
    match model {
        "SourceCreate" => {
            serde_json::from_value::<SourceCreate>(body.clone()).and_then(serde_json::to_value)
        }
        "SourceUpdate" => {
            serde_json::from_value::<SourceUpdate>(body.clone()).and_then(serde_json::to_value)
        }
        "TenantSourceCreate" => serde_json::from_value::<TenantSourceCreate>(body.clone())
            .and_then(serde_json::to_value),
        "TenantSourceUpdate" => serde_json::from_value::<TenantSourceUpdate>(body.clone())
            .and_then(serde_json::to_value),
        "TokenUpdate" => {
            serde_json::from_value::<TokenUpdate>(body.clone()).and_then(serde_json::to_value)
        }
        "RevisionOnly" => {
            serde_json::from_value::<RevisionOnly>(body.clone()).and_then(serde_json::to_value)
        }
        "SourceView" => {
            serde_json::from_value::<SourceView>(body.clone()).and_then(serde_json::to_value)
        }
        other => panic!("the fixture names a model this port does not know: {other}"),
    }
}

#[test]
fn every_source_body_matches_the_reference() {
    let fixtures = oracle();
    let cases = fixtures["source_bodies"].as_array().expect("source bodies");
    assert!(cases.len() >= 20, "the fixture must carry the full table");
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let model = case["model"].as_str().expect("model");
        let expected_ok = case["ok"].as_bool().expect("verdict");
        let result = parse_and_dump(model, &case["body"]);
        assert_eq!(
            result.is_ok(),
            expected_ok,
            "{name} ({model}) disagreed with the reference"
        );
        if let Ok(value) = result {
            let dump: Value = serde_json::from_str(case["dump"].as_str().expect("dump"))
                .expect("the fixture dump is JSON");
            assert_eq!(value, dump, "{name} ({model}) serialised differently");
        }
    }
}

#[test]
fn every_tenant_url_verdict_matches_the_reference() {
    let fixtures = oracle();
    let cases = fixtures["tenant_url_cases"]
        .as_array()
        .expect("tenant URL cases");
    assert!(cases.len() >= 10, "the fixture must carry the full table");
    for case in cases {
        let value = case["value"].as_str().expect("value");
        let allow_path = case["allow_path"].as_bool().expect("allow_path");
        let expected_ok = case["ok"].as_bool().expect("verdict");
        let result = checked_tenant_url(value, allow_path);
        assert_eq!(
            result.is_ok(),
            expected_ok,
            "checked_tenant_url({value:?}, {allow_path}) disagreed with the reference"
        );
        if let Err(error) = result {
            assert_eq!(
                error.to_string(),
                case["message"].as_str().expect("message"),
                "{value:?}"
            );
        }
    }
}

/// A minimal body for each auth kind the fixture names; the field values are valid members of
/// the kind's own contract, so only the secret rule under test varies.
fn minimal_auth(kind: &str) -> Value {
    match kind {
        "none" => json!({"kind": "none"}),
        "licence" => json!({"kind": "licence", "app_key": "coding"}),
        "static_bearer" => json!({"kind": "static_bearer"}),
        "static_header" => json!({"kind": "static_header", "header": "X-Api-Key"}),
        "query_param" => json!({"kind": "query_param", "param": "api_key"}),
        "basic" => json!({"kind": "basic", "username": "svc"}),
        "oauth2_client_credentials" => json!({
            "kind": "oauth2_client_credentials",
            "token_url": "https://auth.example.com/token",
            "client_id": "client-1",
        }),
        other => panic!("the fixture names an auth kind this port does not know: {other}"),
    }
}

#[test]
fn every_auth_kind_needs_the_secret_the_reference_says() {
    let fixtures = oracle();
    let kinds = fixtures["auth_kinds"].as_object().expect("auth kinds");
    assert_eq!(kinds.len(), 7, "the fixture must carry every kind");
    for (kind, verdict) in kinds {
        let auth: SourceAuth =
            serde_json::from_value(minimal_auth(kind)).expect("the fixture's kind parses");
        assert_eq!(auth.kind(), kind.as_str());
        assert_eq!(
            needs_secret(&auth),
            verdict["needs_secret"].as_bool().expect("needs_secret"),
            "{kind}"
        );
    }
}

#[test]
fn the_forbidden_header_set_matches_the_reference() {
    let fixtures = oracle();
    let expected: BTreeSet<&str> = fixtures["forbidden_headers"]
        .as_array()
        .expect("forbidden headers")
        .iter()
        .map(|value| value.as_str().expect("header"))
        .collect();
    let actual: BTreeSet<&str> = FORBIDDEN_HEADERS.into_iter().collect();
    assert_eq!(actual, expected);
}

#[test]
fn every_reserved_header_is_refused_by_the_header_kind() {
    let fixtures = oracle();
    let mut headers: Vec<&str> = fixtures["forbidden_headers"]
        .as_array()
        .expect("forbidden headers")
        .iter()
        .map(|value| value.as_str().expect("header"))
        .collect();
    // `authorization` is reserved by the same validator but is not in the set: the licence and
    // static-bearer kinds own it.
    headers.push("authorization");
    for header in headers {
        let body = json!({"kind": "static_header", "header": header});
        assert!(
            serde_json::from_value::<SourceAuth>(body).is_err(),
            "{header} must be reserved"
        );
    }
}
